      const details=node('details','qsv-details');details.append(node('summary','',tr('处理条件','Requirements')),node('p','',tr('仅处理已完整核验、相关进程停止且无遗留租约的固定安装。若相关进程或管理记录仍在，请由远端管理员核实；现有停止／恢复按钮也可能受待更新记录阻挡。原安装的四文件检查不够。','Only a fully verified fixed installation with related processes stopped and no remaining leases is eligible. Have the remote administrator verify remaining processes or management records; existing Stop/Recover actions may also be blocked by the update record. The original installation’s four-file check is insufficient.')));body.append(details);
